internal data class SettingsSearchTarget(val category: Int, val key: String, val title: Int, val keywords: List<Int> = emptyList()) {
    val label get() = if (title == R.string.tunnel_packet_size) "MTU" else AppText.text(title)
    fun matches(query: String): Boolean {
        val text = (listOf(label) + keywords.map { AppText.text(it) }).joinToString(" ").lowercase().replace('ё', 'е')
        return query.trim().lowercase().replace('ё', 'е').split(Regex("\\s+")).all { it in text }
    }
}

